#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."
trap 'rc=$?; printf "%s\n" "$rc" > logs/final_stream_audits.exit' EXIT
test "$(cat logs/focus_post_b.exit)" = 0
root="$(cd .. && pwd)"
image='ghcr.io/librelane/librelane@sha256:02d50f259d483979e126ef188a50f5b61e1d285b9d538312f280b087439b0302'
docker run --rm --name faultv-w25-final-vias --user 1000:1000 --memory=3000m --cpus=2 -v "$root:/work" -w /work/week25_closure "$image" openroad -exit -python scripts/export_native_vias.py runs/focus_post_b/1-openroad-fillinsertion/fault_v_asic_top.odb reports/final_native_vias.json > logs/final_via_audit.log 2>&1
docker run --rm --name faultv-w25-final-pg-geometry --user 1000:1000 --memory=3000m --cpus=2 -v "$root:/work" -w /work/week25_closure "$image" openroad -exit -python scripts/export_pg_contact_geometry.py runs/focus_post_b/1-openroad-fillinsertion/fault_v_asic_top.odb reports/final_pg_contact_geometry.json > logs/final_pg_geometry.log 2>&1
docker run --rm --name faultv-w25-final-stream --user 1000:1000 --memory=4000m --cpus=2 -e AUDIT_CORE_GDS=/work/week25_closure/runs/focus_post_b/2-klayout-streamout/fault_v_asic_top.gds -e AUDIT_MACRO_GDS=/work/week25_closure/macros/sky130_sram_2kbyte_1rw1r_32x512_8.orphan_trim_dedup.gds -e AUDIT_REPORT=reports/final_macro_audit.json -v "$root:/work" -w /work/week25_closure "$image" bash -c 'set -e; python3 scripts/audit_stream_macro.py; python3 scripts/audit_final_stdcell_stream.py runs/focus_post_b/2-klayout-streamout/fault_v_asic_top.gds runs/focus_post_b/1-openroad-fillinsertion/fault_v_asic_top.def reports/final_stdcell_audit.json reports/final_native_vias.json; python3 scripts/audit_pg_contacts.py reports/final_pg_contact_geometry.json reports/final_pg_contacts.json' > logs/final_stream_audits.log 2>&1
docker run --rm --name faultv-w25-final-filled-drc --user 1000:1000 --memory=7000m --cpus=2 -e ROUTE_DRC_ODB=/runtime/final_filled.odb -e ROUTE_DRC_REPORT=/work/week25_closure/reports/final_filled_independent.json -v "$root:/work" -v /var/tmp/faultv-w25-closure-20261101:/runtime:ro -w /work/week25_closure "$image" openroad -exit -python /work/routing/scripts/native_route_drc.py > logs/final_filled_independent.log 2>&1
docker run --rm --name faultv-w25-final-filled-connectivity --user 1000:1000 --memory=3000m --cpus=2 -v "$root:/work" -v /var/tmp/faultv-w25-closure-20261101:/runtime:ro -w /work/week25_closure "$image" openroad -exit -python scripts/audit_all_signal_connectivity.py /runtime/final_filled.odb reports/final_filled_all_connectivity.json > logs/final_filled_connectivity.log 2>&1
